def process(identity_theft_clean) -> pd.DataFrame:
    return identity_theft_clean[
        (identity_theft_clean['Theft_Type'] == 'Bank Account') &
        (identity_theft_clean['Theft_Subtype'] == 'New Accounts')
    ]

def process(filter_bank_new_accounts, report_type_clean) -> pd.DataFrame:
    bank_new_accounts = filter_bank_new_accounts['Num_Reports'].values[0]
    total_reports = report_type_clean['Num_Reports'].values[0]
    proportion = bank_new_accounts / total_reports
    proportion_rounded = round(proportion, 4)
    return pd.DataFrame({'Proportion': [proportion_rounded]})

def process(filter_bank_new_accounts, report_type_clean) -> pd.DataFrame:
    bank_new = filter_bank_new_accounts['Num_Reports'].iloc[0]
    total_identity_theft = report_type_clean['Num_Reports'].iloc[0]
    proportion = bank_new / total_identity_theft
    return pd.DataFrame({'Proportion': [round(proportion, 4)]})
